package com.careerpilot.modules.jobmatch.entity;
import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="job_match_skills") @Getter @Setter @NoArgsConstructor
public class JobMatchSkill{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="job_match_id")private JobMatch jobMatch;@Column(name="skill_name",nullable=false,length=120)private String skillName;@Column(name="normalized_skill_name",nullable=false,length=120)private String normalizedSkillName;@Enumerated(EnumType.STRING)@Column(name="match_status",nullable=false,length=20)private MatchStatus matchStatus;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private SkillImportance importance;@Column(nullable=false,length=40)private String source;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private SkillPriority priority;@Column(nullable=false,length=500)private String evidence;@Column(nullable=false,length=700)private String recommendation;@Column(name="created_at",nullable=false)private Instant createdAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}}
